import{_ as p,l as A,o as e,c as o,v as r,p as l,x as t,d as h,i as n,S as s}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Hyper-NA","description":"","frontmatter":{"title":"Hyper-NA","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/hyper-na.md","filePath":"litho/hyper-na.md","lastUpdated":1789023840000}'),E={name:"litho/hyper-na.md"};function N(d,a,m,c,_,u){const i=A("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="hyper-na" tabindex="-1">Hyper-NA <a class="header-anchor" href="#hyper-na" aria-label="Permalink to &quot;Hyper-NA&quot;">​</a></h1><div class="epigraph"><p>0.55 之后若还要靠抬孔径换单次节距，孔径讨论会进入 Hyper-NA；那是公开展望与可行性研究，不是一张可以下单的量产规格书。</p><footer>—— 对照 ASML / Zeiss 在路线图场合对 0.55 之后孔径的公开讨论</footer></div><p><a href="/litho/euv-double-pattern">上一课</a>把 0.33 上「单次不够」收成 LELE/SADP 或等待 High-NA。缺口是：0.55 自己也会在更后面的节距上不够——那时是 High-NA 双重，还是再抬 NA？ASML 在 imec ITF 一类公开场合把 Hyper-NA 写进路线图展望，口径讨论落在 0.75 量级（亦有 0.85 的研究口吻），时间尺度说到 2030 前后；官方澄清过这是愿景与可行性研究。本课只钉孔径讨论里多出来的物理税，不当作 EXE 的下一款产品手册。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分辨率仍按 \\(\\lambda/\\mathrm{NA}\\)。波长锁在 13.5 nm，再缩单次半节距只能加 NA 或再降 \\(k_1\\)。High-NA 已经用变形光学才把掩模侧角度从多层膜墙上救回来；再往上，主光线、偏振、焦深、胶厚、场尺寸会同时变本加厉。问题是：在「High-NA 双重」与「Hyper-NA 单次」之间，光学是否还存在一个可镀膜、可扫描、可涂胶的点。</p><p>公开能写的只有量级。van den Brink 等把高于约 0.7 的 NA 说成 2030 前后才更看得见的机会；Zeiss 被描述为开始透镜设计研究。没有公开的场尺寸、wph、镜面张数或量产导入年，可当合同用。缺口因此是机制税，不是规格表。</p><h3 id="不要把路线图当采购项" tabindex="-1">不要把路线图当采购项 <a class="header-anchor" href="#不要把路线图当采购项" aria-label="Permalink to &quot;不要把路线图当采购项&quot;">​</a></h3><p>把 Hyper-NA 写成「0.75 NA、某年、某 wph」会越权。ASML 对媒体的澄清是：可行性研究进行中。本课把 0.75 当作公开讨论过的目标量级，用来算 \\(\\mathrm{NA}^2\\) 税，而不是宣布一台尚未承诺的扫描机。</p><p><span class="marginnote">Hyper-NA 不是 High-NA 的改名。High-NA 专指已在建的 0.55 EXE 平台。把两者混称「更高 NA 的 EUV」，在展望课里会把已出货与未承诺焊在一起。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>展望里的光学逻辑与 EXE 同构，只是数字更狠。掩模侧 NA 随硅片 NA / 倍率涨，变形倍率可能还要再拆，场可能更小，拼接与套刻预算更紧。焦深再按 \\(\\mathrm{NA}^2\\) 掉，<a href="/litho/high-na-resist-budget">胶厚预算</a>要从 0.55 的薄膜再往下，倒塌、吸收与随机三角一起收紧。边缘光线角大到偏振对比崩溃时，偏振器会挡掉光子，产率税与随机税同一方向。</p><p>另一条公开对照是：不抬 NA，而在 0.55 上双重，或继续用 0.33 双重加设计规则。Hyper-NA 只在「单次节距的经济性」赢过这些路径时才值得把蔡司镜子再做一代——那是系统经济，不是本课能算出来的净现值。</p><h3 id="与-0-33-0-55-机队的并存" tabindex="-1">与 0.33 / 0.55 机队的并存 <a class="header-anchor" href="#与-0-33-0-55-机队的并存" aria-label="Permalink to &quot;与 0.33 / 0.55 机队的并存&quot;">​</a></h3><p>即使展望兑现，历史也是多代并存：干式与浸没、NXE 与 EXE。Hyper-NA 若出现，也只会吃最紧的层，而不是替换全部 EUV。讨论应落在「哪一层的单次截止」，而不是「哪一年全球切换」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>NA 提高：截止频率上移，单次 \\(k_1\\) 墙后移。同时 DOF \\(\\propto 1/\\mathrm{NA}^2\\)，膜更薄，光子体积更小，随机悬崖前移。矢量效应在更大孔径角上把 TM 对比打掉，可能逼出偏振控制，光源光子更贵。多层膜布拉格峰对角度更挑剔，掩模三维与阴影更重，SMO 与波前校正的负担上升。每一条都是 0.55 已经付过的税的加码，没有新的免费物理。</p><p>电子模糊、二次电子射程不随 NA 变。光学截止再往下走，会撞上胶与二次电子的模糊地板——公开讨论里这被当作「孔径不是无限可抬」的理由之一。那是材料与统计的墙，不是镜子没磨好。</p><p><span class="marginnote">不要用实验室显微镜的 0.75 NA 类比扫描机。EUV 投影是多层反射、真空、扫描同步与全芯片场；显微镜物镜的 NA 数字不能平移成 EXE 的下一档规格。</span></p>',18)),(e(),l(s,null,{default:t(()=>[n(i,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXE%5B%22High-NA%200.55%20%E5%8D%95%E6%AC%A1%22%5D%20--%3E%20NEXT%5B%22%E6%9B%B4%E5%AF%86%E8%8A%82%E8%B7%9D%22%5D%0A%20%20NEXT%20--%3E%20DP%5B%220.55%20%E5%8F%8C%E9%87%8D%22%5D%0A%20%20NEXT%20--%3E%20HYP%5B%22Hyper-NA%20%E5%AD%94%E5%BE%84%E5%B1%95%E6%9C%9B%22%5D%0A%20%20HYP%20--%3E%20TAX%5B%22DOF%20%2F%20%E5%81%8F%E6%8C%AF%20%2F%20%E5%9C%BA%20%2F%20%E9%9A%8F%E6%9C%BA%22%5D%0A%20%20DP%20--%3E%20TAX2%5B%22%E5%A5%97%E5%88%BB%E4%B8%8E%E5%BE%AA%E7%8E%AF%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给出未公开的光学处方，不把 0.75 或 0.85 写成已冻结的产品 NA。时间点是展望，会随可行性研究移动。出口管制与镜子产能对 0.55 已经是瓶颈，下一代只会更稀缺。计算光刻、胶、掩模三维必须先在 EXE 上成熟，否则孔径讨论没有工艺落点。把实验室显微镜或掩模显微镜上的高 NA 演示写成扫描机视野，会把场尺寸与扫描同步两笔账漏掉。</p><p>后课默认：0.55 之后的孔径是展望项；量产决策仍在单次 High-NA、High-NA 双重与设计规则之间做，不以 Hyper-NA 为已交付工具。</p><p>计算光刻课程从下一单元的 OPC 开始，不再把未承诺的孔径当作已冻结的成像合同。</p><p><span class="marginnote">引用路线图时写「公开展望 / 可行性研究」，不要写成「ASML 已公布 Hyper-NA 量产机规格」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Hyper-NA 是 0.55 之后再抬 EUV 孔径的公开展望，讨论量级约 0.75，不是量产规格。</li><li>物理税是更薄焦深、更薄胶、更重偏振与掩模三维，随机三角会更紧。</li><li>替代路径是 High-NA 双重与设计规则，不是只有抬 NA 一条路。</li><li>模糊与二次电子不随 NA 消失，孔径有材料地板。</li><li>出处：ASML / Zeiss 在路线图与 ITF 等场合对 High-NA 之后孔径的公开讨论。</li></ul>',7))])}const T=p(E,[["render",N]]);export{f as __pageData,T as default};
